// ₹30-50L+ for leads). Every job is OPEN, published in the last 30
// days, and posted by the bootstrap admin user as a stand-in until
// real recruiters claim their company pages.

interface SeedJob {
  /** Slug fragment — final slug = ${this}-${company-slug}. */
  slugSeed: string;
  companySlug: string;
  title: string;
  description: string;
  responsibilities: string;
  requirements: string;
  benefits?: string;
  profileMode: ProfileMode;
  employmentType: EmploymentType;
  workMode: WorkMode;
  seniorityLevel: SeniorityLevel;
  locations: string[];
  experienceMin: number;
  experienceMax: number;
  /** Salary bounds in INR per year (NOT lakhs — full rupees). */
  salaryMin: number;
  salaryMax: number;
  audience?: JobAudience;
  /** Days ago this listing was "published". 0 = today, 30 = a month ago. */
  publishedDaysAgo: number;
  evDomainSlugs: string[];
  skillNames: string[];
  /** External career-page URL. When set, the public /jobs/[id] page
      surfaces a "Apply on company site" CTA and skips the internal
      apply form entirely — used for jobs aggregated from third-party
      career sites where we don't own the ATS. */
  applicationUrl?: string;
}

