async function seedInstitutions(): Promise<void> {
  console.log(`🌱 Seeding ${INSTITUTIONS.length} EV institutions (universities / colleges / R&D / training)...`);
  let upserted = 0;
  for (const inst of INSTITUTIONS) {
    await db.institution.upsert({
      where: { slug: inst.slug },
      create: {
        slug: inst.slug,
        name: inst.name,
        type: inst.type,
        shortName: inst.shortName ?? null,
        city: inst.city ?? null,
        state: inst.state ?? null,
        country: inst.country ?? "IN",
        website: inst.website ?? null,
        about: inst.about ?? null,
        foundedYear: inst.foundedYear ?? null,
        affiliation: inst.affiliation ?? null,
        verificationStatus: InstitutionVerification.VERIFIED,
        verifiedAt: new Date(),
      },
      update: {
        name: inst.name,
        type: inst.type,
        shortName: inst.shortName ?? null,
        city: inst.city ?? null,
        state: inst.state ?? null,
        country: inst.country ?? "IN",
        website: inst.website ?? null,
        about: inst.about ?? null,
        foundedYear: inst.foundedYear ?? null,
        affiliation: inst.affiliation ?? null,
        verificationStatus: InstitutionVerification.VERIFIED,
      },
    });
    upserted += 1;
  }
  const byType = INSTITUTIONS.reduce<Record<string, number>>((acc, i) => {
    acc[i.type] = (acc[i.type] ?? 0) + 1;
    return acc;
  }, {});
  console.log(
    `   → ${upserted} institutions seeded · ` +
      Object.entries(byType)
        .map(([t, n]) => `${n} ${t.toLowerCase()}`)
        .join(" · "),
  );
}

async function main() {
  console.log("🌱 Seeding EV domains...");
  for (let i = 0; i < EV_DOMAINS.length; i++) {
    const d = EV_DOMAINS[i];
    await db.eVDomain.upsert({
      where: { slug: d.slug },
      create: { ...d, order: i },
      update: { name: d.name, description: d.description, order: i },
    });
  }

  console.log("🌱 Seeding canonical EV skills...");
  for (const [domainSlug, skills] of Object.entries(SKILLS_BY_DOMAIN)) {
    const domain = await db.eVDomain.findUnique({ where: { slug: domainSlug } });
    if (!domain) continue;
    for (const name of skills) {
      const slug = name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");
      await db.skill.upsert({
        where: { slug },
        create: { slug, name, evDomainId: domain.id, category: domain.name },
        update: { name, evDomainId: domain.id, category: domain.name },
      });
    }
  }
  const skillCount = await db.skill.count();
  console.log(`   → ${skillCount} skills total`);

  console.log("🌱 Seeding bootstrap admin user...");
  const adminEmail = process.env.SEED_ADMIN_EMAIL ?? "admin@emobility.careers";
  const adminPassword = process.env.SEED_ADMIN_PASSWORD ?? "ChangeMe123!";
  const passwordHash = await argon2.hash(adminPassword);
  const admin = await db.user.upsert({
    where: { email: adminEmail },
    create: {
      email: adminEmail,
      name: "Platform Admin",
      passwordHash,
      role: "ADMIN",
      emailVerifiedAt: new Date(),
    },
    update: { role: "ADMIN" },
    select: { id: true },
  });
  console.log(`   → Admin: ${adminEmail} / ${adminPassword} (CHANGE ME)`);

  // Companies + salaries + jobs + institutions. Each seeder is
  // idempotent — companies + institutions upsert by slug, salaries
  // delete-then-insert by `ip = "seed"`, jobs delete-then-insert by
  // `applicationEmail = "seed@emobility.careers"`.
  const companyIds = await seedCompanies(admin.id);
  await seedSalaries(companyIds);
  await seedJobs(admin.id, companyIds);
  await seedInstitutions();

  console.log("✅ Seed complete.");
}

main()
  .catch((err) => {
    console.error(err);
    process.exit(1);
  })
  .finally(() => db.$disconnect());
